import type { Metadata } from 'next'
import { SITE_NAME, SITE_URL } from '@/content/site'

/** Generated by the `app/og/route.tsx` handler. */
export const OG_IMAGE = {
  alt: 'Roshni Peswani, Dietista-Nutricionista en Las Palmas',
  height: 630,
  url: '/og',
  width: 1200,
}

type PageSeo = {
  description: string
  path: string
  title: string
  type?: 'article' | 'website'
}

/**
 * Builds a consistent `Metadata` object for a public page: self-referencing
 * canonical, Open Graph, and Twitter card. Keeping this in one place avoids the
 * classic bug where a subpage inherits the homepage social preview.
 */
export function pageMetadata({
  description,
  path,
  title,
  type = 'website',
}: PageSeo): Metadata {
  return {
    alternates: { canonical: path },
    description,
    openGraph: {
      description,
      images: [OG_IMAGE],
      locale: 'es_ES',
      siteName: SITE_NAME,
      title,
      type,
      url: path,
    },
    title,
    twitter: {
      card: 'summary_large_image',
      description,
      images: [OG_IMAGE.url],
      title,
    },
  }
}

/** Absolute URL helper for schema/work that needs a fully-qualified address. */
export function absoluteUrl(path: string) {
  return new URL(path, SITE_URL).toString()
}
